abstract class Vehicle {
    abstract void start();
}
class Car extends Vehicle {
    @Override
    void start() {
        System.out.println("Car starts");
    }
}
// Inside main:
Vehicle vehicle = new Car();
vehicle.start();

class Animal {
    void eat() { System.out.println("Eating"); }
}
class Dog extends Animal {
    void bark() { System.out.println("Barking"); }
}
// Inside main:
Dog dog = new Dog();
dog.eat();
dog.bark();
